      title: { en: 'Design basics every builder needs', he: 'יסודות עיצוב שכל בונה צריך' },
      tldr: {
        en: 'Good design is mostly clear decisions: what matters most (hierarchy), breathing room (spacing), readable type, and enough contrast. Make it accessible, mobile-first, and ready for Hebrew right-to-left. Then tell Claude the feeling and the limits, not just the content.',
        he: 'עיצוב טוב הוא בעיקר החלטות ברורות: מה הכי חשוב (היררכיה), מרווח נשימה (ריווח), טקסט קריא, וניגודיות מספיקה. עושים אותו נגיש, קודם לטלפון, ומוכן לעברית מימין לשמאל. ואז אומרים ל-Claude את התחושה ואת הגבולות — לא רק את התוכן.'
      },
      goals: {
        en: ['Name the four basics of visual design', 'Check colour contrast and accessibility', 'Write a design brief that gets Claude past the generic look'],
        he: ['להכיר את ארבעת היסודות של עיצוב חזותי', 'לבדוק ניגודיות צבע ונגישות', 'לכתוב תדריך עיצוב שמוציא את Claude מהמראה הגנרי']
      },
      terms: [['UI / UX', 'UI: איך זה נראה. UX: איך זה מרגיש להשתמש.'], ['Hierarchy', 'היררכיה: מה העין רואה ראשון, שני, שלישי.'], ['Contrast', 'ניגודיות: ההבדל בין צבע הטקסט לרקע.'], ['Accessibility (a11y)', 'נגישות: שכולם יוכלו להשתמש, גם עם מוגבלות.'], ['RTL', 'Right-to-left: כיוון כתיבה מימין לשמאל, כמו עברית.']],
      blocks: [
        { t: 'p', en: 'You do not need to be a designer to ship good-looking tools. You need a few principles, a way to check your work, and the habit of giving Claude a real brief.', he: 'לא צריך להיות מעצבים כדי להוציא כלים שנראים טוב. צריך כמה עקרונות, דרך לבדוק את העבודה, והרגל לתת ל-Claude תדריך אמיתי.' },
        { t: 'cards', en: [{ title: 'Hierarchy', tag: 'What first?', body: 'One clear main thing per screen. Size, weight and position tell the eye where to go.', c: 'l4' }, { title: 'Spacing', tag: 'Room to breathe', body: 'Consistent gaps from a small scale (4, 8, 16, 24…). Related things sit closer together.', c: 'l1' }, { title: 'Typography', tag: 'Easy to read', body: 'One or two typefaces, a clear size scale, body text of at least 16px on phones.', c: 'l2' }, { title: 'Colour and contrast', tag: 'Meaning, not decoration', body: 'A small palette with one accent, and enough contrast to read in sunlight.', c: 'l3' }], he: [{ title: 'היררכיה', tag: 'מה קודם?', body: 'דבר ראשי אחד ברור בכל מסך. גודל, עובי ומיקום אומרים לעין לאן להסתכל.', c: 'l4' }, { title: 'ריווח', tag: 'מקום לנשום', body: 'מרווחים קבועים מסולם קטן (4, 8, 16, 24…). דברים קשורים קרובים יותר זה לזה.', c: 'l1' }, { title: 'טיפוגרפיה', tag: 'קל לקרוא', body: 'גופן אחד או שניים, סולם גדלים ברור, וטקסט רגיל של 16px לפחות בטלפון.', c: 'l2' }, { title: 'צבע וניגודיות', tag: 'משמעות, לא קישוט', body: 'פלטה קטנה עם צבע הדגשה אחד, וניגודיות שמספיקה כדי לקרוא גם בשמש.', c: 'l3' }] },
        { t: 'h', en: 'Check your contrast', he: 'בודקים ניגודיות' },
        { t: 'widget', name: 'contrast' },
        { t: 'list', en: ['**Contrast:** at least 4.5:1 for normal text, 3:1 for large text and icons.', '**Tap targets:** buttons and links at least 44px tall on phones.', '**Labels:** every input has a visible label, not just placeholder text.', '**Images:** meaningful images have alt text.', '**Keyboard and focus:** you can reach everything with the keyboard, and you can see where you are.', '**Not colour alone:** errors say what is wrong in words, not just in red.'], he: ['**ניגודיות:** לפחות 4.5:1 לטקסט רגיל, ו-3:1 לטקסט גדול ולאייקונים.', '**אזורי לחיצה:** כפתורים וקישורים בגובה 44px לפחות בטלפון.', '**תוויות:** לכל שדה יש תווית גלויה, לא רק טקסט אפור בתוכו.', '**תמונות:** לתמונות עם משמעות יש טקסט חלופי (alt).', '**מקלדת ופוקוס:** אפשר להגיע לכל דבר עם המקלדת, ורואים איפה נמצאים.', '**לא רק צבע:** שגיאה אומרת במילים מה לא בסדר, לא רק באדום.'] },
        { t: 'callout', kind: 'tip', title: { en: 'Hebrew and right-to-left', he: 'עברית ומימין לשמאל' }, en: { title: 'Hebrew and right-to-left', body: 'In Hebrew the whole layout mirrors: navigation, back arrows, progress bars. In CSS use **logical properties** (`margin-inline-start`, `padding-inline`) instead of left/right, so one design works in both directions. Numbers, code and English names stay left-to-right inside the text.' }, he: { title: 'עברית ומימין לשמאל', body: 'בעברית כל הפריסה מתהפכת: ניווט, חצי "חזרה", פסי התקדמות. ב-CSS משתמשים ב**מאפיינים לוגיים** (`margin-inline-start`, ‏`padding-inline`) במקום left/right, וכך עיצוב אחד עובד לשני הכיוונים. מספרים, קוד ושמות באנגלית נשארים משמאל לימין בתוך הטקסט.' } },
        { t: 'h', en: 'Brief Claude like a designer', he: 'נותנים ל-Claude תדריך כמו למעצב' },
        { t: 'compare', en: { badT: 'Gets the generic look', bad: ['“Make a nice website for my client.”', '“Make it modern.”', '“Use nice colours.”'], goodT: 'Gets a real design', good: ['Audience and goal: “Tourists and locals choosing a spice shop in the market, on their phones.”', 'Mood words: “warm, crafted, generous — not luxury, not cartoon.”', 'Brand facts: colours, fonts, logo, photos, tone of voice.', 'References: “like a printed market sign; see the attached photos.”', 'Limits: “mobile first, Hebrew and English, AA contrast, no stock-photo people.”'] }, he: { badT: 'יוצא גנרי', bad: ['"תעשה אתר יפה ללקוח שלי."', '"תעשה את זה מודרני."', '"תשתמש בצבעים יפים."'], goodT: 'יוצא עיצוב אמיתי', good: ['קהל ומטרה: "תיירים ומקומיים שבוחרים חנות תבלינים בשוק, מהטלפון."', 'מילות תחושה: "חם, בעבודת יד, נדיב — לא יוקרתי, לא מצויר."', 'עובדות מותג: צבעים, גופנים, לוגו, תמונות, טון דיבור.', 'השראה: "כמו שלט שוק מודפס; ראו את התמונות המצורפות."', 'גבולות: "קודם לטלפון, עברית ואנגלית, ניגודיות AA, בלי תמונות סטוק של אנשים."'] } },
        { t: 'key', en: { title: 'Describe the feeling and the limits, not just the content', body: 'Without direction, AI design drifts to the average of everything it has seen. Mood words, brand facts, references and constraints pull it toward something specific to your client.' }, he: { title: 'מתארים את התחושה ואת הגבולות, לא רק את התוכן', body: 'בלי כיוון, עיצוב של AI נמשך לממוצע של כל מה שראה. מילות תחושה, עובדות מותג, השראה וגבולות מושכים אותו למשהו שמתאים רק ללקוח שלכם.' } },
        { t: 'callout', kind: 'simple', he: 'ארבעה יסודות: מה הכי חשוב, מרווחים קבועים, טקסט קריא, ניגודיות מספיקה. ובתדריך ל-Claude — תחושה, מותג, השראה וגבולות.' }
      ],
